bool isTrackVisible(String path) {
  final listContext = listKey.currentContext;
  final rowContext = rowKeys[path]?.currentContext;
  if (listContext == null || rowContext == null) return false;

  final list = listContext.findRenderObject();
  final row = rowContext.findRenderObject();
  if (list is! RenderBox || row is! RenderBox) return false;
  if (!list.hasSize || !row.hasSize) return false;

  final listRect = list.localToGlobal(Offset.zero) & list.size;
  final rowRect = row.localToGlobal(Offset.zero) & row.size;
  return rowRect.overlaps(listRect);
}

